#!/usr/bin/env node
'use strict'

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, '')
    .trim()
    .replace(/[\s-]+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function main() {
  const given = process.argv.slice(2).join(' ')
  if (given !== '') {
    console.log(slugify(given))
    return
  }
  let input = ''
  process.stdin.setEncoding('utf8')
  process.stdin.on('data', chunk => (input += chunk))
  process.stdin.on('end', () => console.log(slugify(input)))
}

if (require.main === module) main()
module.exports = { slugify }

